ALTER TABLE goals ADD COLUMN version bigint NOT NULL DEFAULT 1 CHECK(version>=1), ADD COLUMN current_measurement_id text NOT NULL DEFAULT '', ADD COLUMN measurement_coverage_from timestamptz, ADD COLUMN legacy_observed_current double precision, ADD COLUMN legacy_observed_unit text NOT NULL DEFAULT '';
UPDATE goals SET measurement_coverage_from=now(),legacy_observed_current=current,legacy_observed_unit=unit;
CREATE TABLE goal_measurements(id text PRIMARY KEY,company_id text NOT NULL REFERENCES companies(id),goal_id text NOT NULL REFERENCES goals(id),actor_id text NOT NULL,value double precision NOT NULL,effective_at timestamptz NOT NULL,reason text NOT NULL,corrects_id text NOT NULL DEFAULT '',created_at timestamptz NOT NULL,goal_version_after bigint NOT NULL,unit text NOT NULL,baseline double precision NOT NULL,target double precision NOT NULL,evidence jsonb NOT NULL DEFAULT '[]',UNIQUE(company_id,goal_id,goal_version_after),CHECK(length(reason)>0 AND length(reason)<=4000),CHECK(value NOT IN ('NaN'::float8,'Infinity'::float8,'-Infinity'::float8)));
CREATE UNIQUE INDEX goal_correction_leaf ON goal_measurements(company_id,goal_id,corrects_id) WHERE corrects_id <> '';
CREATE INDEX goal_measurement_history ON goal_measurements(company_id,goal_id,goal_version_after DESC,id);
CREATE TABLE goal_revisions(id text PRIMARY KEY,company_id text NOT NULL,goal_id text NOT NULL,actor_id text NOT NULL,reason text NOT NULL,created_at timestamptz NOT NULL,version bigint NOT NULL,"before" jsonb NOT NULL,"after" jsonb NOT NULL,UNIQUE(company_id,goal_id,version));
CREATE TABLE goal_audits(id text PRIMARY KEY,company_id text NOT NULL,goal_id text NOT NULL,actor_id text NOT NULL,action text NOT NULL,version bigint NOT NULL,created_at timestamptz NOT NULL);
